ee:message.ee:set-payload:
%dw 2.0
output application/json

---
// filter customers data basing on totalAmount being only above 5000.
{
  "customers": payload.customers map (c) -> {
	  "customerId": c.customerId,
	  "name": c.name ++ "_" ++ c.region,
	  "region": c.region,
	  "orders": c.orders filter (o) -> o.totalAmount > 5000
	}
}

%dw 2.0
output application/json

var customers = payload.customers default []

// filter and update the orders object
var orders = flatten(
  customers map (customer) -> 
    (customer.orders default []) map (order) -> {
      orderId: order.orderId,
      customerId: customer.customerId,
      orderDate: order.orderDate,
      totalAmount: order.totalAmount
    }
)

// transform products data basing on id, name and total prices of products
var productsSummary = ((flatten(customers map ((item) -> flatten(item.orders.products)))) map ((item, index) -> {
      productId: item.productId,
      productName: item.name,
      price: item.price
  })) groupBy ((item, index) -> item.productId) pluck ((value) -> {
      productId: value.productId[0],
      productName: value.productName[0],
      totalPrice: sum(value.price)
  })

---
{
  "customers": customers,
  "orders": orders,
  "productsSummary": productsSummary
}
